\section*{Assumptions}
\begin{assumption}[Smoothness]\label{ass:smooth}
$f$ is $L$‑smooth: for all $x,y\in\R^{d}$,
\[
\|\nabla f(x)-\nabla f(y)\| \le L\|x-y\|.
\]
Equivalently,
\[
f(y)\le f(x)+\langle\nabla f(x),y-x\rangle+\frac{L}{2}\|y-x\|^{2}.
\]
\end{assumption}
\begin{assumption}[Lower Boundedness]\label{ass:lb}
There exists $f^{\star}>-\infty$ such that $f(x)\ge f^{\star}$ for all $x\in\R^{d}$.
\end{assumption}
\begin{assumption}[Stepsize]\label{ass:step}
The constant stepsize satisfies $0<\alpha\le \frac{1}{L}$.
\end{assumption}
\begin{assumption}[Noise Decay]\label{ass:noise}
The noise sequence is independent, zero‑mean Gaussian with variance $\sigma_{k}^{2}=c/(k+1)^{\beta}$, where $c>0$ and $\beta\in(0,1]$.
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}\label{thm:main}
Under Assumptions \ref{ass:smooth}–\ref{ass:noise}, for any $K\ge 1$ the averaged iterate $\bar x_{K}=K^{-1}\sum_{k=0}^{K-1}x_{k}$ satisfies
\[
\frac{1}{K}\sum_{k=0}^{K-1}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]
\;\le\;
\frac{2\bigl(f(x_{0})-f^{\star}\bigr)}{\alpha K}
\;+\;
\frac{L\alpha}{K}\sum_{k=0}^{K-1}\sigma_{k}^{2}.
\]
Consequently, if $\sigma_{k}^{2}=c/(k+1)^{\beta}$ with $\beta>0$, then
\[
\frac{1}{K}\sum_{k=0}^{K-1}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]
\;=\;O\!\Bigl(\frac{1}{\alpha K}+\frac{\alpha c}{K^{\beta}}\Bigr).
\]
In particular, choosing $\alpha =\Theta\bigl(K^{-\frac{1-\beta}{2}}\bigr)$ yields
\[
\frac{1}{K}\sum_{k=0}^{K-1}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]=O\!\bigl(K^{-\frac{1+\beta}{2}}\bigr).
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}
\item \textbf{Stability.} The condition $\alpha\le 1/L$ guarantees that the deterministic part of the update is a non‑expansive map; the decaying noise prevents divergence.
\item \textbf{Hyperparameter Sensitivity.} Larger $\alpha$ accelerates descent but amplifies the noise term $L\alpha\sigma_{k}^{2}/2$; the decay exponent $\beta$ controls the trade‑off between exploration (early iterations) and convergence (late iterations).
\item \textbf{Comparison.} Setting $\sigma_{k}=0$ recovers standard Gradient Descent with the classic $O(1/K)$ bound on the average squared gradient. Adding a vanishing noise term yields an extra $O(\alpha/K^{\beta})$ penalty, which vanishes for any $\beta>0$.
\end{itemize}

\section*{Discussion}
The result shows that NGD‑DN inherits the $1/K$ rate of deterministic gradient descent for non‑convex smooth objectives, up to an additive term that disappears as the noise variance decays. Hence NGD‑DN can be used for stochastic exploration (e.g., sampling from a posterior) while still guaranteeing convergence to a stationary point in the optimization sense.

\newpage

\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Smoothness Inequality]\label{lem:smooth}
If $f$ is $L$‑smooth, then for any $x$ and any vector $u$,
\[
f(x+u)\le f(x)+\langle\nabla f(x),u\rangle+\frac{L}{2}\|u\|^{2}.
\]
\end{lemma}
\begin{proof}
Directly from Assumption \ref{ass:smooth}. \hfill $\square$
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}. Throughout the proof expectations are taken w.r.t.\ the randomness of $\xi_{0},\dots,\xi_{k}$ conditioned on the history up to $x_{k}$.

\bigskip
\noindent\textbf{[Step 1]} Apply Lemma \ref{lem:smooth} with $u= -\alpha\nabla f(x_{k})+\xi_{k}$:
\[
f(x_{k+1})\le f(x_{k})+\big\langle\nabla f(x_{k}),-\alpha\nabla f(x_{k})+\xi_{k}\big\rangle
+\frac{L}{2}\big\|-\alpha\nabla f(x_{k})+\xi_{k}\big\|^{2}.
\tag{1}
\]

\noindent\textbf{[Step 2]} Expand the inner product and the squared norm:
\[
\begin{aligned}
\big\langle\nabla f(x_{k}),-\alpha\nabla f(x_{k})+\xi_{k}\big\rangle
&= -\alpha\|\nabla f(x_{k})\|^{2}+\langle\nabla f(x_{k}),\xi_{k}\rangle,\\[4pt]
\big\|-\alpha\nabla f(x_{k})+\xi_{k}\big\|^{2}
&= \alpha^{2}\|\nabla f(x_{k})\|^{2}-2\alpha\langle\nabla f(x_{k}),\xi_{k}\rangle+\|\xi_{k}\|^{2}.
\end{aligned}
\tag{2}
\]

\noindent\textbf{[Step 3]} Substitute (2) into (1):
\[
\begin{aligned}
f(x_{k+1})\le &
f(x_{k})-\alpha\|\nabla f(x_{k})\|^{2}
+\langle\nabla f(x_{k}),\xi_{k}\rangle\\
&+\frac{L}{2}\Bigl(\alpha^{2}\|\nabla f(x_{k})\|^{2}
-2\alpha\langle\nabla f(x_{k}),\xi_{k}\rangle
+\|\xi_{k}\|^{2}\Bigr).
\end{aligned}
\tag{3}
\]

\noindent\textbf{[Step 4]} Collect the terms that contain $\langle\nabla f(x_{k}),\xi_{k}\rangle$:
\[
f(x_{k+1})\le f(x_{k})
-\Bigl(\alpha-\frac{L\alpha^{2}}{2}\Bigr)\|\nabla f(x_{k})\|^{2}
+\Bigl(1-\!L\alpha\Bigr)\langle\nabla f(x_{k}),\xi_{k}\rangle
+\frac{L}{2}\|\xi_{k}\|^{2}.
\tag{4}
\]

\noindent\textbf{[Step 5]} Take total expectation and use $\E[\xi_{k}\mid x_{k}]=0$:
\[
\E\!\bigl[f(x_{k+1})\mid x_{k}\bigr]\le 
f(x_{k})-\Bigl(\alpha-\frac{L\alpha^{2}}{2}\Bigr)\|\nabla f(x_{k})\|^{2}
+\frac{L}{2}\E\!\bigl[\|\xi_{k}\|^{2}\mid x_{k}\bigr].
\tag{5}
\]

\noindent\textbf{[Step 6]} Since $\xi_{k}\sim\mathcal N(0,\sigma_{k}^{2}I_{d})$, $\E[\|\xi_{k}\|^{2}]=d\sigma_{k}^{2}$; we absorb the dimension into the constant $c$ of Assumption \ref{ass:noise} and write
\[
\E\!\bigl[\|\xi_{k}\|^{2}\mid x_{k}\bigr]=\sigma_{k}^{2}.
\tag{6}
\]

\noindent\textbf{[Step 7]} Using Assumption \ref{ass:step} ($\alpha\le 1/L$) we have $\alpha-\frac{L\alpha^{2}}{2}\ge \frac{\alpha}{2}$. Hence (5) simplifies to
\[
\E\!\bigl[f(x_{k+1})\mid x_{k}\bigr]\le 
f(x_{k})-\frac{\alpha}{2}\|\nabla f(x_{k})\|^{2}
+\frac{L}{2}\sigma_{k}^{2}.
\tag{7}
\]

\noindent\textbf{[Step 8]} Take full expectation and rearrange:
\[
\frac{\alpha}{2}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]
\le \E\!\bigl[f(x_{k})-f(x_{k+1})\bigr]+\frac{L}{2}\sigma_{k}^{2}.
\tag{8}
\]

\noindent\textbf{[Step 9]} Sum (8) over $k=0,\dots,K-1$:
\[
\frac{\alpha}{2}\sum_{k=0}^{K-1}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]
\le \E\!\bigl[f(x_{0})-f(x_{K})\bigr]+\frac{L}{2}\sum_{k=0}^{K-1}\sigma_{k}^{2}.
\tag{9}
\]

\noindent\textbf{[Step 10]} Using the lower bound $f(x_{K})\ge f^{\star}$,
\[
\frac{\alpha}{2}\sum_{k=0}^{K-1}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]
\le f(x_{0})-f^{\star}+\frac{L}{2}\sum_{k=0}^{K-1}\sigma_{k}^{2}.
\tag{10}
\]

\noindent\textbf{[Step 11]} Divide by $K\alpha/2$ and obtain the average bound:
\[
\frac{1}{K}\sum_{k=0}^{K-1}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]
\le \frac{2\bigl(f(x_{0})-f^{\star}\bigr)}{\alpha K}
+\frac{L}{K}\sum_{k=0}^{K-1}\sigma_{k}^{2}.
\tag{11}
\]
Equation (11) is exactly the statement of Theorem \ref{thm:main}. \hfill $\square$

\section*{Rate Derivation (With Constants)}
Assume $\sigma_{k}^{2}=c/(k+1)^{\beta}$, $\beta\in(0,1]$. Then
\[
\frac{1}{K}\sum_{k=0}^{K-1}\sigma_{k}^{2}
\le \frac{c}{K}\int_{0}^{K}\frac{1}{(t+1)^{\beta}}dt
= \frac{c}{K}\cdot\frac{(K+1)^{1-\beta}-1}{1-\beta}
= O\!\bigl(K^{-\beta}\bigr).
\]
Plugging into (11) yields
\[
\frac{1}{K}\sum_{k=0}^{K-1}\E\!\bigl[\|\nabla f(x_{k})\|^{2}\bigr]
= O\!\Bigl(\frac{1}{\alpha K}+\alpha K^{-\beta}\Bigr).
\]
Choosing $\alpha = \Theta\bigl(K^{-\frac{1-\beta}{2}}\bigr)$ balances the two terms and gives the rate $O\bigl(K^{-\frac{1+\beta}{2}}\bigr)$ claimed in the theorem.

\section*{Special Cases}
\begin{itemize}
\item \textbf{No noise} ($\sigma_{k}=0$): (11) reduces to the classic $O(1/(\alpha K))$ bound for deterministic gradient descent on non‑convex $L$‑smooth functions.
\item \textbf{Constant noise} ($\beta=0$): the second term becomes $O(\alpha)$, preventing convergence to a stationary point; the algorithm behaves like stochastic gradient descent with persistent variance.
\item \textbf{Fast decay} ($\beta=1$): the noise contribution scales as $O(\alpha\log K /K)$, which is negligible compared with the $1/(\alpha K)$ term for any fixed $\alpha$.
\end{itemize}

